{
  name: 'Появляется по времени',
  args: {
    notice: createNotice()
  },
  render: () => renderNoticeStory(createNotice()),
  play: async ({
    canvasElement
  }) => {
    const canvas = within(canvasElement);
    await waitFor(() => {
      expect(canvas.getByTestId('tracked-actions')).toHaveTextContent('view');
      expect(canvas.getByText('Новая функция в профиле')).toBeVisible();
    });
  }
}

{
  name: 'Появляется после двух кликов',
  args: {
    notice: createNotice({
      trigger: {
        type: 'click',
        value: 2
      }
    })
  },
  render: () => renderNoticeStory(createNotice({
    trigger: {
      type: 'click',
      value: 2
    }
  })),
  play: async ({
    canvasElement
  }) => {
    const canvas = within(canvasElement);
    const triggerButton = canvas.getByTestId('trigger-button');
    await userEvent.click(triggerButton);
    await userEvent.click(triggerButton);
    await waitFor(() => {
      expect(canvas.getByTestId('page-clicks')).toHaveTextContent('2');
      expect(canvas.getByTestId('tracked-actions')).toHaveTextContent('view');
      expect(canvas.getByText('Новая функция в профиле')).toBeVisible();
    });
  }
}

{
  name: 'Отслеживает ссылку и закрытие',
  args: {
    notice: createNotice({
      banner: {
        id: 'storybook-notice-link',
        title: 'Обновление справки',
        emoji: '📌',
        content: 'Подготовили короткий гайд. <a href="#guide">Открыть инструкцию</a>.'
      }
    })
  },
  render: () => renderNoticeStory(createNotice({
    banner: {
      id: 'storybook-notice-link',
      title: 'Обновление справки',
      emoji: '📌',
      content: 'Подготовили короткий гайд. <a href="#guide">Открыть инструкцию</a>.'
    }
  })),
  play: async ({
    canvasElement
  }) => {
    const canvas = within(canvasElement);
    await waitFor(() => {
      expect(canvas.getByTestId('tracked-actions')).toHaveTextContent('view');
      expect(canvas.getByRole('link', {
        name: 'Открыть инструкцию'
      })).toBeVisible();
    });
    await userEvent.click(canvas.getByRole('link', {
      name: 'Открыть инструкцию'
    }));
    await userEvent.click(canvas.getByRole('button', {
      name: 'Закрыть уведомление'
    }));
    await waitFor(() => {
      expect(canvas.getByTestId('tracked-actions')).toHaveTextContent('view, click, close');
      expect(canvas.getByTestId('close-count')).toHaveTextContent('1');
    });
  }
}

