{
  name: 'Выбор специализаций',
  render: args => ({
    components: {
      BaseButton,
      CpVacancyImportGroupsModal
    },
    setup() {
      const modalRef = ref<InstanceType<typeof CpVacancyImportGroupsModal> | null>(null);
      const selectedGroups = ref<number[]>([]);
      function openModal() {
        modalRef.value?.open();
      }
      function handleImportGroups(groupsIds: number[]) {
        selectedGroups.value = groupsIds;
        modalRef.value?.close();
      }
      onMounted(openModal);
      return {
        args,
        modalRef,
        selectedGroups,
        openModal,
        handleImportGroups
      };
    },
    template: `
      <div class="min-h-[360px] bg-ui-gray-bg p-6">
        <BaseButton @click="openModal">Открыть модалку</BaseButton>
        <p v-if="selectedGroups.length" class="mt-4 text-body-m text-ui-gray-2">
          Выбраны группы: {{ selectedGroups.join(', ') }}
        </p>
        <CpVacancyImportGroupsModal
          ref="modalRef"
          :groups="args.groups"
          :unpublished-vacancies-link="args.unpublishedVacanciesLink"
          :loading="args.loading"
          @import-groups="handleImportGroups"
        />
      </div>
    `
  })
}

